INSERT INTO announcement (announcement_id, title, body, category, posted_by, hostel_id, posted_date, expiry_date, is_pinned) VALUES (1, 'Water supply interruption on Saturday', 'Water supply will be shut off between 10 AM and 2 PM on Saturday for overhead tank cleaning. Please store water in advance.', 'Maintenance', 1, NULL, TO_TIMESTAMP('2026-08-14 09:43:09', 'YYYY-MM-DD HH24:MI:SS'), DATE '2026-09-13', 'N');
INSERT INTO announcement (announcement_id, title, body, category, posted_by, hostel_id, posted_date, expiry_date, is_pinned) VALUES (2, 'Diwali leave applications', 'Students going home for Diwali must apply for leave through the portal at least three days before departure.', 'General', 1, NULL, TO_TIMESTAMP('2026-08-18 13:25:23', 'YYYY-MM-DD HH24:MI:SS'), DATE '2026-09-17', 'N');
INSERT INTO announcement (announcement_id, title, body, category, posted_by, hostel_id, posted_date, expiry_date, is_pinned) VALUES (3, 'Mess feedback week', 'The mess committee is collecting suggestions for the next month''s menu. Share your feedback with your floor representative.', 'Mess', 1, NULL, TO_TIMESTAMP('2026-08-05 13:52:33', 'YYYY-MM-DD HH24:MI:SS'), DATE '2026-09-04', 'N');
INSERT INTO announcement (announcement_id, title, body, category, posted_by, hostel_id, posted_date, expiry_date, is_pinned) VALUES (4, 'Fire drill on Thursday', 'A mandatory fire evacuation drill will be conducted on Thursday at 6 PM. All residents must assemble at the main lawn.', 'Urgent', 1, NULL, TO_TIMESTAMP('2026-08-10 13:19:36', 'YYYY-MM-DD HH24:MI:SS'), DATE '2026-09-09', 'Y');
INSERT INTO announcement (announcement_id, title, body, category, posted_by, hostel_id, posted_date, expiry_date, is_pinned) VALUES (5, 'Wi-Fi maintenance window', 'The hostel network will be upgraded on Sunday from 1 AM to 5 AM. Internet access may be intermittent.', 'Maintenance', 1, NULL, TO_TIMESTAMP('2026-08-09 20:46:51', 'YYYY-MM-DD HH24:MI:SS'), DATE '2026-09-08', 'N');
INSERT INTO announcement (announcement_id, title, body, category, posted_by, hostel_id, posted_date, expiry_date, is_pinned) VALUES (6, 'Hostel day celebrations', 'Hostel day will be held next Friday evening with cultural events and a special dinner.', 'Event', 1, NULL, TO_TIMESTAMP('2026-10-03 10:44:37', 'YYYY-MM-DD HH24:MI:SS'), DATE '2026-11-02', 'N');
INSERT INTO announcement (announcement_id, title, body, category, posted_by, hostel_id, posted_date, expiry_date, is_pinned) VALUES (7, 'Room inspection schedule', 'Wardens will carry out room inspections floor-wise during the coming week. Keep rooms clean and electrical appliances unplugged.', 'General', 1, NULL, TO_TIMESTAMP('2026-09-01 13:02:59', 'YYYY-MM-DD HH24:MI:SS'), DATE '2026-10-01', 'N');
INSERT INTO announcement (announcement_id, title, body, category, posted_by, hostel_id, posted_date, expiry_date, is_pinned) VALUES (8, 'Pest control drive', 'Pest control treatment will be carried out floor-wise. Keep food items sealed and cupboards closed.', 'Maintenance', 1, NULL, TO_TIMESTAMP('2026-09-26 18:12:43', 'YYYY-MM-DD HH24:MI:SS'), DATE '2026-10-26', 'N');
INSERT INTO announcement (announcement_id, title, body, category, posted_by, hostel_id, posted_date, expiry_date, is_pinned) VALUES (9, 'Fee payment reminder', 'Odd semester hostel and mess fees were due on 31 July. Students with pending dues must clear them at the earliest.', 'Urgent', 1, NULL, TO_TIMESTAMP('2026-09-13 21:55:16', 'YYYY-MM-DD HH24:MI:SS'), DATE '2026-10-13', 'Y');
INSERT INTO announcement (announcement_id, title, body, category, posted_by, hostel_id, posted_date, expiry_date, is_pinned) VALUES (10, 'Yoga sessions every morning', 'Free yoga sessions are held at the hostel terrace from 6:15 AM to 7:00 AM on weekdays.', 'Event', 1, NULL, TO_TIMESTAMP('2026-08-17 20:29:55', 'YYYY-MM-DD HH24:MI:SS'), DATE '2026-09-16', 'N');
INSERT INTO announcement (announcement_id, title, body, category, posted_by, hostel_id, posted_date, expiry_date, is_pinned) VALUES (11, 'Lost and found items on display', 'Unclaimed items reported in the lost and found portal are kept at the warden office. Collect them with ID proof.', 'General', 1, NULL, TO_TIMESTAMP('2026-08-14 21:45:43', 'YYYY-MM-DD HH24:MI:SS'), DATE '2026-09-13', 'N');
INSERT INTO announcement (announcement_id, title, body, category, posted_by, hostel_id, posted_date, expiry_date, is_pinned) VALUES (12, 'Night curfew timings', 'Hostel gates close at 10:30 PM. Late entry requires prior approval from the warden.', 'General', 1, NULL, TO_TIMESTAMP('2026-08-28 19:00:19', 'YYYY-MM-DD HH24:MI:SS'), DATE '2026-09-27', 'N');
INSERT INTO announcement (announcement_id, title, body, category, posted_by, hostel_id, posted_date, expiry_date, is_pinned) VALUES (13, 'Water supply interruption on Saturday (Aravali Block)', 'Water supply will be shut off between 10 AM and 2 PM on Saturday for overhead tank cleaning. Please store water in advance.', 'Maintenance', 5, 1, TO_TIMESTAMP('2026-08-31 09:31:57', 'YYYY-MM-DD HH24:MI:SS'), DATE '2026-09-30', 'N');
INSERT INTO announcement (announcement_id, title, body, category, posted_by, hostel_id, posted_date, expiry_date, is_pinned) VALUES (14, 'Diwali leave applications (Nilgiri Block)', 'Students going home for Diwali must apply for leave through the portal at least three days before departure.', 'General', 12, 2, TO_TIMESTAMP('2026-09-05 08:07:01', 'YYYY-MM-DD HH24:MI:SS'), DATE '2026-10-05', 'N');
INSERT INTO announcement (announcement_id, title, body, category, posted_by, hostel_id, posted_date, expiry_date, is_pinned) VALUES (15, 'Mess feedback week (Shivalik Block)', 'The mess committee is collecting suggestions for the next month''s menu. Share your feedback with your floor representative.', 'Mess', 19, 3, TO_TIMESTAMP('2026-08-21 09:07:46', 'YYYY-MM-DD HH24:MI:SS'), DATE '2026-09-20', 'N');
INSERT INTO announcement (announcement_id, title, body, category, posted_by, hostel_id, posted_date, expiry_date, is_pinned) VALUES (16, 'Fire drill on Thursday (Vindhya Block)', 'A mandatory fire evacuation drill will be conducted on Thursday at 6 PM. All residents must assemble at the main lawn.', 'Urgent', 28, 4, TO_TIMESTAMP('2026-08-04 18:48:31', 'YYYY-MM-DD HH24:MI:SS'), DATE '2026-09-03', 'Y');
INSERT INTO announcement (announcement_id, title, body, category, posted_by, hostel_id, posted_date, expiry_date, is_pinned) VALUES (17, 'Wi-Fi maintenance window (Ganga Block)', 'The hostel network will be upgraded on Sunday from 1 AM to 5 AM. Internet access may be intermittent.', 'Maintenance', 36, 5, TO_TIMESTAMP('2026-09-27 13:50:05', 'YYYY-MM-DD HH24:MI:SS'), DATE '2026-10-27', 'N');
INSERT INTO announcement (announcement_id, title, body, category, posted_by, hostel_id, posted_date, expiry_date, is_pinned) VALUES (18, 'Hostel day celebrations (Kaveri Block)', 'Hostel day will be held next Friday evening with cultural events and a special dinner.', 'Event', 44, 6, TO_TIMESTAMP('2026-08-08 20:38:08', 'YYYY-MM-DD HH24:MI:SS'), DATE '2026-09-07', 'N');
INSERT INTO announcement (announcement_id, title, body, category, posted_by, hostel_id, posted_date, expiry_date, is_pinned) VALUES (19, 'Room inspection schedule (Aravali Block)', 'Wardens will carry out room inspections floor-wise during the coming week. Keep rooms clean and electrical appliances unplugged.', 'General', 2, 1, TO_TIMESTAMP('2026-08-26 13:02:56', 'YYYY-MM-DD HH24:MI:SS'), DATE '2026-09-25', 'N');
INSERT INTO announcement (announcement_id, title, body, category, posted_by, hostel_id, posted_date, expiry_date, is_pinned) VALUES (20, 'Pest control drive (Nilgiri Block)', 'Pest control treatment will be carried out floor-wise. Keep food items sealed and cupboards closed.', 'Maintenance', 11, 2, TO_TIMESTAMP('2026-09-20 11:04:10', 'YYYY-MM-DD HH24:MI:SS'), DATE '2026-10-20', 'N');
INSERT INTO announcement (announcement_id, title, body, category, posted_by, hostel_id, posted_date, expiry_date, is_pinned) VALUES (21, 'Fee payment reminder (Shivalik Block)', 'Odd semester hostel and mess fees were due on 31 July. Students with pending dues must clear them at the earliest.', 'Urgent', 19, 3, TO_TIMESTAMP('2026-08-17 18:25:48', 'YYYY-MM-DD HH24:MI:SS'), DATE '2026-09-16', 'Y');
